/** језгро_вриједност 안의 연결형 бајт_вриједност ток_вриједност. Ethernet/TCP 패킷 스택이 아닌 루프백 socket слој_вриједност. */
public final class ток_Мрежа {
    static int[] стање_вриједност = new int[16], порт_вриједност = new int[16], 짝 = new int[16], 상대창구 = new int[16], чекај_вриједност = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], подаци = new int[16 * 1024];
    static int Даље_ставка = 50000;
    static int потврдити(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && стање_вриједност[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int број_порта) { for (int петља_индекс = 0; петља_индекс < 16; петља_индекс++) if (стање_вриједност[петља_индекс] != 0 && 묶임[петља_индекс] != 0 && порт_вриједност[петља_индекс] == број_порта) return true; return false; }
    public static int Направи_унос() {
        for (int петља_индекс = 0; петља_индекс < 16; петља_индекс++) if (стање_вриједност[петља_индекс] == 0) { стање_вриједност[петља_индекс] = 1; 상대창구[петља_индекс] = порт_вриједност[петља_индекс] = 앞[петља_индекс] = 수[петља_индекс] = чекај_вриједност[петља_индекс] = 묶임[петља_индекс] = 0; 짝[петља_индекс] = -1; return петља_индекс + 40; }
        return -24;
    }
    public static int повезати_крајња_тачка(int 열린파일번호, int 통신주소, int број_порта) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (стање_вриједност[петља_индекс] != 1 || број_порта < 0 || број_порта > 65535) return -22;
        if (број_порта == 0) { do { број_порта = Даље_ставка++; if (Даље_ставка > 65535) Даље_ставка = 50000; } while (사용중(број_порта)); }
        if (사용중(број_порта)) return -98; порт_вриједност[петља_индекс] = број_порта; 묶임[петља_индекс] = 1; стање_вриједност[петља_индекс] = 2; return 0;
    }
    public static int слушати_крајња_тачка(int 열린파일번호, int 연결대기한도) { int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 2 || 연결대기한도 < 1) return -22; стање_вриједност[петља_индекс] = 3; return 0; }
    public static int Повежи_се(int 열린파일번호, int 통신주소, int број_порта) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (број_порта < 1 || број_порта > 65535 || стање_вриједност[петља_индекс] > 2) return -22;
        int 수신쪽 = -1; for (int унутрашње_позиција = 0; унутрашње_позиција < 16; унутрашње_позиција++) if (стање_вриједност[унутрашње_позиција] == 3 && порт_вриједност[унутрашње_позиција] == број_порта) 수신쪽 = унутрашње_позиција;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int унутрашње_позиција = 0; унутрашње_позиција < 16; унутрашње_позиција++) if (чекај_вриједност[унутрашње_позиција] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (стање_вриједност[петља_индекс] == 1) { int 처리값 = повезати_крајња_тачка(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = Направи_унос(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        стање_вриједност[петља_индекс] = стање_вриједност[다른번호] = 4; 짝[петља_индекс] = 다른번호; 짝[다른번호] = петља_индекс; порт_вриједност[다른번호] = број_порта; 상대창구[петља_индекс] = број_порта; 상대창구[다른번호] = порт_вриједност[петља_индекс]; чекај_вриједност[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int прихвати_веза(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 3) return -22; for (int унутрашње_позиција = 0; унутрашње_позиција < 16; унутрашње_позиција++) if (стање_вриједност[унутрашње_позиција] != 0 && чекај_вриједност[унутрашње_позиција] == петља_индекс + 1) { чекај_вриједност[унутрашње_позиција] = 0; return унутрашње_позиција + 40; } return -11; }
    public static int Пише(int 열린파일번호, int 항목수) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int унутрашње_позиција = 짝[петља_индекс]; if (унутрашње_позиција < 0) return -32; int 총수 = 1024 - 수[унутрашње_позиција]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int Поређење_позиција = 0; Поређење_позиција < 총수; Поређење_позиција++) подаци[унутрашње_позиција * 1024 + (앞[унутрашње_позиција] + 수[унутрашње_позиција] + Поређење_позиција) % 1024] = 되돌림망.Напред_вриједност[Поређење_позиција]; 수[унутрашње_позиција] += 총수; return 총수;
    }
    public static int Чита(int 열린파일번호, int 항목수) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9; if (стање_вриједност[петља_индекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[петља_индекс] == 0) return 짝[петља_индекс] < 0 ? 0 : -11; if (항목수 > 수[петља_индекс]) 항목수 = 수[петља_индекс];
        for (int Поређење_позиција = 0; Поређење_позиција < 항목수; Поређење_позиција++) 되돌림망.Напред_вриједност[Поређење_позиција] = подаци[петља_индекс * 1024 + (앞[петља_индекс] + Поређење_позиција) % 1024]; 앞[петља_индекс] = (앞[петља_индекс] + 항목수) % 1024; 수[петља_индекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); return петља_индекс < 0 ? -9 : порт_вриједност[петља_индекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int петља_индекс = потврдити(열린파일번호); return петља_индекс < 0 ? -9 : 상대창구[петља_индекс]; }
    public static int Затворен(int 열린파일번호) {
        int петља_индекс = потврдити(열린파일번호); if (петља_индекс < 0) return -9;
        if (стање_вриједност[петља_индекс] == 3) for (int унутрашње_позиција = 0; унутрашње_позиција < 16; унутрашње_позиција++) if (чекај_вриједност[унутрашње_позиција] == петља_индекс + 1) { if (짝[унутрашње_позиција] >= 0) 짝[짝[унутрашње_позиција]] = -1; стање_вриједност[унутрашње_позиција] = чекај_вриједност[унутрашње_позиција] = 묶임[унутрашње_позиција] = 0; }
        if (짝[петља_индекс] >= 0) 짝[짝[петља_индекс]] = -1; стање_вриједност[петља_индекс] = 묶임[петља_индекс] = 수[петља_индекс] = чекај_вриједност[петља_индекс] = 0; return 0;
    }
}
